// ── ตรวจสอบ x-line-signature ตามมาตรฐาน LINE Messaging API ──────────────
// HMAC-SHA256(raw request body, channel secret) แล้ว base64 → ต้องตรงกับ header
const crypto = require('crypto');

// ⚠️ ใส่ Channel Secret ของคุณตรงนี้ (หรือตั้ง env LINE_CHANNEL_SECRET)
let CHANNEL_SECRET = 'PASTE_YOUR_LINE_CHANNEL_SECRET';
try { if ($env && $env.LINE_CHANNEL_SECRET) CHANNEL_SECRET = $env.LINE_CHANNEL_SECRET; } catch (e) { /* n8n cloud block env */ }

const item = $input.first();
const headers = item.json.headers || {};
const signature = headers['x-line-signature'] || headers['X-Line-Signature'] || '';

// ดึง raw body (ตั้ง Raw Body = true ที่ node LINE Webhook)
let rawBody = '';
if (item.binary && item.binary.data && item.binary.data.data) {
  rawBody = Buffer.from(item.binary.data.data, 'base64').toString('utf8');
} else if (typeof item.json.body === 'string') {
  rawBody = item.json.body;
} else {
  rawBody = JSON.stringify(item.json.body || {});
}

const expected = crypto.createHmac('SHA256', CHANNEL_SECRET).update(rawBody).digest('base64');

const skipCheck = CHANNEL_SECRET === 'PASTE_YOUR_LINE_CHANNEL_SECRET';
if (!skipCheck) {
  const a = Buffer.from(expected);
  const b = Buffer.from(String(signature));
  const ok = a.length === b.length && crypto.timingSafeEqual(a, b);
  if (!ok) {
    throw new Error('LINE signature verification failed — ปฏิเสธ request นี้ (อาจไม่ได้มาจาก LINE)');
  }
}

let body = {};
try { body = JSON.parse(rawBody || '{}'); } catch (e) { body = {}; }

return [{ json: { body, signature_valid: !skipCheck, signature_checked: !skipCheck } }];

// ── แตกข้อมูลจาก LINE event → 1 item ต่อ 1 ข้อความ ───────────────────────
const payload = $input.first().json.body || {};
const events = payload.events || [];

const nowBkk = () => {
  const d = new Date(Date.now() + 7 * 60 * 60 * 1000);
  return d.toISOString().replace('T', ' ').slice(0, 19);
};

const out = [];
let seq = 0;
for (const ev of events) {
  if (ev.type !== 'message') continue;          // ข้าม follow/unfollow/postback
  seq += 1;
  const msg = ev.message || {};
  out.push({
    json: {
      event_type: ev.type,
      message_type: msg.type || 'unknown',
      message_id: msg.id || '',
      message_text: msg.text || '',
      line_user_id: (ev.source || {}).userId || '',
      source_type: (ev.source || {}).type || '',
      reply_token: ev.replyToken || '',
      line_timestamp: ev.timestamp || null,
      received_at: nowBkk(),
      log_id: 'LOG-' + Date.now() + '-' + seq,
      is_text: msg.type === 'text' && !!msg.text,
    },
  });
}

// LINE ยิง verify request ตอนตั้งค่า webhook (events = []) → ไม่ต้องทำอะไรต่อ
return out;

