// ── ดึงผลลัพธ์จาก AI Agent + ผลของ Complaint Ticket Tool (ถ้าถูกเรียก) ──────
const cfg = $('⚙️ Config').first().json;
const agent = $input.first().json || {};

let reply_text = (agent.output || agent.text || '').toString().trim();
if (!reply_text) {
  reply_text = 'ขออภัยค่ะ ตอนนี้น้องอิ่มใจขัดข้องชั่วคราว รบกวนพิมพ์มาใหม่อีกครั้งนะคะ 🙏';
}

// tool ที่ถูกเรียกในเทิร์นนี้
let tools_called = [];
try {
  const steps = agent.intermediateSteps || [];
  tools_called = steps.map((s) => (s.action && s.action.tool) || s.tool).filter(Boolean);
} catch (e) { tools_called = []; }

// ผลการเปิด ticket (node นี้อยู่ใน execution เดียวกัน)
let ticket = null;
try {
  if ($('Complaint Ticket Tool').isExecuted) {
    ticket = $('Complaint Ticket Tool').first().json || null;
  }
} catch (e) { ticket = null; }

const truthy = (v) => v === true || String(v).toUpperCase() === 'TRUE';

const action_requested = ticket ? (ticket.action_requested || 'none') : 'none';
const requires_human_approval = ticket ? truthy(ticket.requires_human_approval) : false;
const is_high_risk = ticket ? truthy(ticket.is_high_risk) : false;

// ── ตรวจ "ความไม่มั่นใจ" ของคำตอบ (ตาข่ายกันพลาดชั้นที่ 2 นอกเหนือจาก system prompt) ──
// ถ้าบอทไม่มั่นใจ ให้ยิงหาแอดมินทันที ดีกว่าปล่อยให้ลูกค้าได้คำตอบมั่ว
const UNCERTAIN = [
  'ไม่แน่ใจ', 'ไม่ทราบ', 'ไม่พบข้อมูล', 'ไม่พบเลขออเดอร์', 'ไม่พบเมนู', 'ไม่มีข้อมูล',
  'ตอบไม่ได้', 'ไม่สามารถตอบ', 'ขอตรวจสอบก่อน', 'อาจจะ', 'น่าจะประมาณ',
  'ขอคุยกับแอดมิน', 'ติดต่อทีมงาน', 'ให้ทีมงานตัวจริง',
];
const ASK_HUMAN = ['แอดมิน', 'คุยกับคน', 'พนักงานตัวจริง', 'ขอเบอร์', 'โทรหา', 'human', 'admin'];

const inboundMsg = (cfg.message_text || '').toString();
const lowConfidenceText = UNCERTAIN.some((k) => reply_text.includes(k));
const customerAsksHuman = ASK_HUMAN.some((k) => inboundMsg.toLowerCase().includes(k.toLowerCase()));
// ถามเป็นคำถามจริงจัง แต่บอทไม่เรียก tool เลย = ตอบจากความจำ → ไม่น่าเชื่อถือ
const answeredWithoutTool = tools_called.length === 0 && inboundMsg.length > 8;

const low_confidence = lowConfidenceText || customerAsksHuman || answeredWithoutTool;

// เส้นทางการทำงาน
let route = 'normal';
let escalate_reason = '';
if (requires_human_approval) {
  route = 'approval';
  escalate_reason = 'ต้องขออนุมัติ: ' + action_requested + (is_high_risk ? ' + high-risk' : '');
} else if (action_requested === 'contact_admin' || action_requested === 'follow_up') {
  route = 'urgent_contact';
  escalate_reason = 'AI ส่งต่อเอง (' + action_requested + ')';
} else if (low_confidence) {
  route = 'urgent_contact';
  escalate_reason = lowConfidenceText ? 'คำตอบส่อว่าไม่มั่นใจ'
    : (customerAsksHuman ? 'ลูกค้าขอคุยกับคน' : 'ตอบโดยไม่ได้เรียก tool ใด ๆ');
}

const endpointMap = {
  refund: 'refunds',
  cancel_order: 'orders/cancel',
  special_discount: 'discounts/issue',
};

return [{
  json: {
    ...cfg,
    reply_text,
    tools_called: tools_called.join(', '),
    tools_called_list: tools_called,
    intent: tools_called.includes('Complaint_Ticket_Tool') || tools_called.includes('Complaint Ticket Tool')
      ? 'complaint'
      : (tools_called.includes('Order_Tool') || tools_called.includes('Order Tool') ? 'order_status'
        : (tools_called.includes('Product_Tool') || tools_called.includes('Product Tool') ? 'product_inquiry'
          : (tools_called.length ? 'faq' : 'smalltalk'))),
    ticket_id: ticket ? (ticket.ticket_id || '') : '',
    ticket_category: ticket ? (ticket.category || '') : '',
    ticket_message: ticket ? (ticket.message || '') : '',
    sentiment: ticket ? (ticket.sentiment || '') : '',
    is_high_risk,
    action_requested,
    requires_human_approval,
    ticket_order_id: ticket ? (ticket.order_id || '') : '',
    route,
    low_confidence,
    escalate_reason,
    action_endpoint: endpointMap[action_requested] || 'tickets/manual-review',
    out_log_id: 'LOG-' + Date.now() + '-out',
    replied_at: new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19),
  },
}];

// ── ลูกค้าขอคุยแอดมินด่วน → ยิงเข้า Discord แบบ log ทันที (ไม่ต้องรออนุมัติ) ──
const j = $input.first().json;
const stamp = new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);

const payload = {
  username: 'อิ่มใจ Alert',
  content: '@here 📞 **ลูกค้าขอคุยกับแอดมินด่วน**',
  embeds: [{
    title: '📞 ' + (j.ticket_id || 'ไม่มี ticket') + ' — ต้องให้แอดมินเข้าดูแล',
    color: 15105570,
    description: j.ticket_message || j.reply_text,
    fields: [
      { name: 'LINE user id', value: '`' + (j.line_user_id || '-') + '`', inline: true },
      { name: 'หมวดหมู่', value: j.ticket_category || '-', inline: true },
      { name: 'Sentiment', value: j.sentiment || '-', inline: true },
      { name: 'ออเดอร์ที่เกี่ยวข้อง', value: j.ticket_order_id || '-', inline: true },
      { name: 'เวลา', value: stamp, inline: true },
      { name: 'เหตุผลที่ส่งต่อ', value: j.escalate_reason || '-', inline: false },
      { name: 'คำถามของลูกค้า', value: (j.message_text || '-').slice(0, 900), inline: false },
      { name: 'บอทตอบไปว่า', value: (j.reply_text || '-').slice(0, 900), inline: false },
      { name: 'สิ่งที่ต้องทำ', value: 'เปิด LINE OA Manager แล้วตอบลูกค้ารายนี้โดยตรง', inline: false },
    ],
    footer: { text: j.admin_contact_note || 'ImJai Cafe & Kitchen' },
  }],
};

return [{ json: { ...j, discord_payload: payload } }];

// ── สร้าง payload แจ้ง Discord + ลิงก์อนุมัติแบบปลอดภัย ────────────────────
// สำคัญ: ลิงก์ไม่ได้ชี้ตรงไปที่ resume URL (กัน crawler ของ Discord กดอนุมัติเอง)
// แต่ชี้ไปหน้ายืนยันที่ต้องกดปุ่มจริง แล้วปุ่มถึงจะ POST เข้า resume URL
const crypto = require('crypto');
const j = $input.first().json;

const secret = j.approval_secret || 'CHANGE_ME_APPROVAL_SECRET';
const ticket_id = j.ticket_id || 'TK-UNKNOWN';
const token = crypto.createHash('sha256').update(ticket_id + '|' + secret).digest('hex').slice(0, 24);

const resumeUrl = $execution.resumeUrl;
const base = (j.public_base_url || '').replace(/\/$/, '');
const mk = (decision) =>
  base + '/webhook/imjai-approval?ticket=' + encodeURIComponent(ticket_id) +
  '&decision=' + decision +
  '&token=' + token +
  '&resume=' + encodeURIComponent(resumeUrl);

const approve_link = mk('approve');
const reject_link = mk('reject');

const stamp = new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);
const actionLabel = {
  refund: '💸 คืนเงิน (Refund)',
  cancel_order: '❌ ยกเลิกออเดอร์ (Cancel Order)',
  special_discount: '🎟️ ส่วนลดพิเศษ (Special Discount)',
}[j.action_requested] || '🔍 ตรวจสอบด้วยคน (High-risk)';

const urgent = j.is_high_risk || j.sentiment === 'Very Negative';

const payload = {
  username: 'อิ่มใจ Approval',
  content: (urgent ? '@here 🚨 **เคสด่วน! ต้องอนุมัติโดยทีมงาน**' : '🔔 **มีเรื่องรออนุมัติ**'),
  embeds: [{
    title: '🎫 ' + ticket_id + ' — ' + actionLabel,
    color: urgent ? 15158332 : 15844367,
    description:
      '**ข้อความลูกค้า**\n>>> ' + (j.ticket_message || '-') + '\n\n' +
      '**กดเพื่อตัดสินใจ (เปิดหน้ายืนยันแล้วกดปุ่มอีกครั้ง)**\n' +
      '✅ [อนุมัติ](' + approve_link + ')  ·  ⛔ [ปฏิเสธ](' + reject_link + ')',
    fields: [
      { name: 'หมวดหมู่', value: j.ticket_category || '-', inline: true },
      { name: 'Sentiment', value: j.sentiment || '-', inline: true },
      { name: 'High-risk', value: j.is_high_risk ? '⚠️ ใช่' : 'ไม่ใช่', inline: true },
      { name: 'สิ่งที่ลูกค้าขอ', value: j.action_requested || 'none', inline: true },
      { name: 'ออเดอร์', value: j.ticket_order_id || '-', inline: true },
      { name: 'LINE user id', value: '`' + (j.line_user_id || '-') + '`', inline: true },
      { name: 'เวลา', value: stamp, inline: false },
    ],
    footer: { text: 'ระบบจะไม่ดำเนินการใด ๆ จนกว่าจะมีคนกดอนุมัติ · หมดเวลาอัตโนมัติใน 24 ชม.' },
  }],
};

return [{ json: { ...j, approval_token: token, resume_url: resumeUrl, approve_link, reject_link, discord_payload: payload, notified_at: stamp } }];

// ── อ่านผลการตัดสินใจจากคน (ถ้าไม่มี = ถือว่าไม่อนุมัติ) ────────────────────
const prev = $('Build Approval Payload').first().json;
const inc = $input.first().json || {};
const body = inc.body || {};
const query = inc.query || {};

const raw = (body.decision || query.decision || '').toString().toLowerCase();
const approved = raw === 'approve' || raw === 'approved' || raw === 'yes';
const timedOut = raw === '';

const approver = body.approver || query.approver || (timedOut ? 'ระบบ (หมดเวลา)' : 'ทีมงาน');
const note = body.note || query.note || '';
const decided_at = new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);

// ข้อความแจ้งลูกค้า
let customer_text;
if (approved) {
  const m = {
    refund: 'ทีมงานอนุมัติการคืนเงินให้เรียบร้อยแล้วค่ะ 🙏 ยอดเงินจะคืนกลับช่องทางที่ชำระภายใน 3–5 วันทำการนะคะ',
    cancel_order: 'ทีมงานอนุมัติการยกเลิกออเดอร์ให้เรียบร้อยแล้วค่ะ 🙏 หากมีการชำระเงินไว้ ทีมงานจะคืนเงินตามช่องทางเดิมค่ะ',
    special_discount: 'ทีมงานอนุมัติส่วนลดชดเชยให้เรียบร้อยแล้วค่ะ 🙏 เดี๋ยวทีมงานจะส่งรายละเอียดส่วนลดตามมาให้นะคะ',
  };
  customer_text = (m[prev.action_requested] ||
    'ทีมงานตรวจสอบเรื่องของคุณลูกค้าเรียบร้อยแล้วค่ะ และกำลังดำเนินการแก้ไขให้นะคะ') +
    '\n\nเลขที่เรื่อง: ' + prev.ticket_id;
} else if (timedOut) {
  customer_text = 'เรื่องของคุณลูกค้ายังอยู่ระหว่างการตรวจสอบของทีมงานนะคะ 🙏 ' +
    'ทีมงานจะรีบติดต่อกลับโดยเร็วที่สุดค่ะ\n\nเลขที่เรื่อง: ' + prev.ticket_id;
} else {
  customer_text = 'ทีมงานตรวจสอบเรื่องของคุณลูกค้าแล้วนะคะ 🙏 ' +
    'กรณีนี้ยังไม่สามารถดำเนินการตามที่ขอได้ค่ะ' +
    (note ? '\nเหตุผล: ' + note : '') +
    '\n\nหากต้องการรายละเอียดเพิ่มเติม ทีมงานยินดีอธิบายให้ค่ะ โทร 02-123-4567\nเลขที่เรื่อง: ' + prev.ticket_id;
}

return [{
  json: {
    ...prev,
    approved,
    timed_out: timedOut,
    decision_raw: raw || 'timeout',
    approver,
    approval_note: note,
    decided_at,
    customer_text,
    new_status: approved ? 'approved_executing' : (timedOut ? 'expired_no_decision' : 'rejected'),
  },
}];

// ── สร้างหน้ายืนยันการอนุมัติ (มือถือกดง่าย) ────────────────────────────────
// ตัว crawler ที่ prefetch ลิงก์จะได้แค่ HTML นี้ ไม่มีทางสั่งอนุมัติได้
// เพราะการอนุมัติจริงต้องกดปุ่ม → ยิง POST เข้า resume URL เท่านั้น
const crypto = require('crypto');

// ⚠️ ต้องตรงกับ approval_secret ใน node ⚙️ Config
let SECRET = 'CHANGE_ME_APPROVAL_SECRET';
try { if ($env && $env.IMJAI_APPROVAL_SECRET) SECRET = $env.IMJAI_APPROVAL_SECRET; } catch (e) {}

const q = $input.first().json.query || {};
const ticket = (q.ticket || '').toString();
const decision = (q.decision || '').toString() === 'approve' ? 'approve' : 'reject';
const token = (q.token || '').toString();
const resume = (q.resume || '').toString();

const expected = crypto.createHash('sha256').update(ticket + '|' + SECRET).digest('hex').slice(0, 24);
const valid = ticket && resume && token === expected;

const esc = (s) => String(s).replace(/&/g, '&amp;').replace(/</g, '&lt;').replace(/>/g, '&gt;').replace(/"/g, '&quot;');

const shell = (inner, bg) => `<!doctype html><html lang="th"><head>
<meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1">
<meta name="robots" content="noindex,nofollow"><title>อนุมัติเรื่องร้องเรียน — อิ่มใจ</title>
<style>
*{box-sizing:border-box}body{margin:0;font-family:-apple-system,BlinkMacSystemFont,"Segoe UI",Roboto,"Noto Sans Thai",sans-serif;
background:${bg};min-height:100vh;display:flex;align-items:center;justify-content:center;padding:20px;color:#1f2933}
.card{background:#fff;border-radius:20px;box-shadow:0 18px 50px rgba(0,0,0,.18);max-width:460px;width:100%;padding:28px}
h1{font-size:20px;margin:0 0 6px}.sub{color:#61707d;font-size:14px;margin:0 0 20px}
.row{display:flex;justify-content:space-between;gap:12px;padding:10px 0;border-bottom:1px solid #eef1f4;font-size:14px}
.row b{color:#61707d;font-weight:500}
button{width:100%;border:0;border-radius:14px;padding:18px;font-size:17px;font-weight:700;color:#fff;cursor:pointer;margin-top:18px}
.ok{background:#16a34a}.no{background:#dc2626}
input{width:100%;padding:12px;border:1px solid #d5dde3;border-radius:12px;margin-top:14px;font-size:15px}
.note{font-size:12px;color:#8a97a3;margin-top:14px;line-height:1.6}
.done{text-align:center}.done .em{font-size:52px}
</style></head><body><div class="card">${inner}</div></body></html>`;

if (!valid) {
  const html = shell(`<div class="done"><div class="em">🚫</div>
    <h1>ลิงก์ไม่ถูกต้องหรือหมดอายุ</h1>
    <p class="sub">ไม่สามารถยืนยันตัวตนของลิงก์นี้ได้ กรุณาเปิดลิงก์จากข้อความแจ้งเตือนใน Discord อีกครั้ง
    หรือติดต่อผู้ดูแลระบบ</p></div>`, '#f1f5f9');
  return [{ json: { html, valid: false } }];
}

const isApprove = decision === 'approve';
const html = shell(`
  <h1>${isApprove ? '✅ ยืนยันการอนุมัติ' : '⛔ ยืนยันการปฏิเสธ'}</h1>
  <p class="sub">ตรวจสอบข้อมูลแล้วกดปุ่มด้านล่างเพื่อยืนยัน ระบบจะดำเนินการหลังกดปุ่มนี้เท่านั้น</p>
  <div class="row"><b>เลขที่เรื่อง</b><span>${esc(ticket)}</span></div>
  <div class="row"><b>การตัดสินใจ</b><span>${isApprove ? 'อนุมัติ' : 'ไม่อนุมัติ'}</span></div>
  <input id="approver" placeholder="ชื่อผู้อนุมัติ (เช่น ผจก.ส้ม)" />
  <input id="note" placeholder="หมายเหตุ (ไม่บังคับ)" />
  <button class="${isApprove ? 'ok' : 'no'}" id="go">${isApprove ? 'ยืนยันอนุมัติ' : 'ยืนยันไม่อนุมัติ'}</button>
  <p class="note">🔒 ลิงก์นี้ไม่ได้สั่งงานด้วยตัวเอง การเปิดหน้านี้ (รวมถึงการ preview ลิงก์อัตโนมัติของ Discord)
  จะไม่ทำให้เกิดการอนุมัติ ต้องมีคนกดปุ่มนี้เท่านั้น</p>
  <script>
  document.getElementById('go').addEventListener('click', async function () {
    var btn = this; btn.disabled = true; btn.textContent = 'กำลังส่ง...';
    try {
      var res = await fetch(${JSON.stringify(resume)}, {
        method: 'POST', headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          decision: ${JSON.stringify(decision)},
          ticket_id: ${JSON.stringify(ticket)},
          approver: document.getElementById('approver').value || 'ทีมงาน',
          note: document.getElementById('note').value || ''
        })
      });
      document.querySelector('.card').innerHTML =
        '<div class="done"><div class="em">' + (res.ok ? '🎉' : '⚠️') + '</div><h1>' +
        (res.ok ? 'บันทึกเรียบร้อยแล้ว' : 'ส่งไม่สำเร็จ') + '</h1><p class="sub">' +
        (res.ok ? 'ระบบกำลังดำเนินการและแจ้งผลกลับลูกค้าทาง LINE ให้อัตโนมัติ ปิดหน้านี้ได้เลยค่ะ'
                : 'เรื่องนี้อาจถูกตัดสินใจไปแล้ว หรือหมดเวลารออนุมัติ (24 ชม.) กรุณาตรวจสอบใน n8n') + '</p></div>';
    } catch (e) {
      btn.disabled = false; btn.textContent = 'ลองอีกครั้ง';
    }
  });
  </script>
`, isApprove ? '#e8f6ed' : '#fdecec');

return [{ json: { html, valid: true, ticket, decision } }];

