// ── แกะข้อมูลการชำระเงินที่ยิงเข้ามา ให้รองรับชื่อฟิลด์หลายแบบ ──────────────
const cfg = $json;
const body = cfg.body || {};
const headers = cfg.headers || {};

const pick = (...keys) => {
  for (const k of keys) {
    if (body[k] !== undefined && body[k] !== null && body[k] !== '') return body[k];
  }
  return '';
};

const order_id = String(pick('order_id', 'orderId', 'order_no', 'ref1') || '').trim();
const amount = pick('amount', 'total', 'paid_amount');
const payment_ref = String(pick('payment_ref', 'ref', 'txn_id', 'transaction_id', 'ref2') || '').trim();
const method = String(pick('method', 'payment_method', 'channel') || 'QR PromptPay').trim();
const secret = String(pick('secret', 'payment_secret') || headers['x-payment-secret'] || '').trim();

const nowBkk = () => new Date(Date.now() + 7 * 3600 * 1000).toISOString().replace('T', ' ').slice(0, 19);
const paid_at = String(pick('paid_at') || '').trim() || nowBkk();

const secretConfigured = cfg.payment_webhook_secret && cfg.payment_webhook_secret !== 'CHANGE_ME_PAYMENT_SECRET';
const secret_valid = !secretConfigured || secret === cfg.payment_webhook_secret;

return [{
  json: {
    ...cfg,
    order_id,
    amount,
    payment_ref,
    method,
    paid_at,
    secret_valid,
    has_required_fields: !!order_id && amount !== '' && amount !== undefined,
  },
}];

// ── รวมข้อมูลการชำระเงิน + แถวออเดอร์ที่เจอ (ถ้าเจอ) ─────────────────────
